using System.Data.Common;
using System.Text.Json;
using BTech.Data;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
namespace BTech.Controllers.V1.AdditionalModules;
[ApiController]
[Microsoft.AspNetCore.Authorization.Authorize]
[Tags("Finance")]
[Route("api/v1")]
public sealed class FinanceAdditionalController : AdditionalApiControllerBase {
 private readonly ApplicationDbContext _db;
 public FinanceAdditionalController(ApplicationDbContext db):base(new AdditionalApiStore(db)){_db=db;}
 private async Task<DbConnection> Open(CancellationToken ct){var c=_db.Database.GetDbConnection();if(c.State!=System.Data.ConnectionState.Open)await c.OpenAsync(ct);return c;}
 private static void P(DbCommand q,string n,object? v){var p=q.CreateParameter();p.ParameterName=n;p.Value=v??DBNull.Value;q.Parameters.Add(p);}
 private static Task<Dictionary<string,object?>> Row(DbDataReader r,CancellationToken ct){var d=new Dictionary<string,object?>();for(int i=0;i<r.FieldCount;i++)d[r.GetName(i)]=r.IsDBNull(i)?null:r.GetValue(i);return Task.FromResult(d);}
 private static async Task<object?> SelectOne(DbConnection c,string sql,string pName,long id,CancellationToken ct){await using var q=c.CreateCommand();q.CommandText=sql;P(q,pName,id);await using var r=await q.ExecuteReaderAsync(ct);return await r.ReadAsync(ct)?await Row(r,ct):null;}
 [HttpGet("fee-students/{studentId:long}/ledger")] public Task<IActionResult> StudentLedger(long studentId)=>List("student-ledger",studentId.ToString());
 [HttpGet("fee-students/{studentId:long}/balance")] public async Task<IActionResult> StudentBalance(long studentId) { var rows=await Store.ListAsync("student-ledger",studentId.ToString(),HttpContext.RequestAborted); return Ok(new{success=true,studentId,balance=0m,ledger=rows}); }
 [HttpGet("fee-structures/{id:long}")] public async Task<IActionResult> GetFeeStructure(long id){var c=await Open(HttpContext.RequestAborted);await BTech.Services.Fees.FeePlanLegacyGuard.EnsureLegacyStructureAsync(c,id);var x=await SelectOne(c,"SELECT * FROM fee_structures WHERE fee_structure_id=@id","@id",id,HttpContext.RequestAborted);return x is null?NotFound(new{success=false,message="Fee structure not found."}):Ok(new{success=true,data=x});}
 [HttpPut("fee-structures/{id:long}")] public async Task<IActionResult> UpdateFeeStructure(long id,[FromBody] JsonElement b){if(b.ValueKind!=JsonValueKind.Object)return BadRequest(new{success=false,message="A JSON object request body is required."});var ct=HttpContext.RequestAborted;var c=await Open(ct);await BTech.Services.Fees.FeePlanLegacyGuard.EnsureLegacyStructureAsync(c,id);await using var q=c.CreateCommand();q.CommandText=@"UPDATE fee_structures SET structure_code=COALESCE(@code,structure_code),structure_group_code=COALESCE(@group,structure_group_code),structure_name=COALESCE(@name,structure_name),college_id=COALESCE(@college,college_id),academic_year_id=COALESCE(@year,academic_year_id),course_id=COALESCE(@course,course_id),branch_id=COALESCE(@branch,branch_id),semester_id=COALESCE(@semester,semester_id),fee_category_id=COALESCE(@category,fee_category_id),amount=COALESCE(@amount,amount),currency_code=COALESCE(@currency,currency_code),effective_from=COALESCE(@from,effective_from),effective_to=COALESCE(@to,effective_to),status=COALESCE(@status,status),updated_at=CURRENT_TIMESTAMP WHERE fee_structure_id=@id";
 object? V(string k)=>b.TryGetProperty(k,out var v)&&v.ValueKind!=JsonValueKind.Null? v.ValueKind==JsonValueKind.String?v.GetString():v.ToString():null;
 P(q,"@code",V("structureCode"));P(q,"@group",V("structureGroupCode"));P(q,"@name",V("structureName"));P(q,"@college",V("collegeId"));P(q,"@year",V("academicYearId"));P(q,"@course",V("courseId"));P(q,"@branch",V("branchId"));P(q,"@semester",V("semesterId"));P(q,"@category",V("feeCategoryId"));P(q,"@amount",V("amount"));P(q,"@currency",V("currencyCode"));P(q,"@from",V("effectiveFrom"));P(q,"@to",V("effectiveTo"));P(q,"@status",V("status"));P(q,"@id",id);var n=await q.ExecuteNonQueryAsync(ct);if(n==0){var exists=await SelectOne(c,"SELECT fee_structure_id FROM fee_structures WHERE fee_structure_id=@id","@id",id,ct);if(exists is null)return NotFound(new{success=false,message="Fee structure not found."});}return Ok(new{success=true,message="Fee structure updated.",id});}
 [HttpDelete("fee-structures/{id:long}")] public async Task<IActionResult> DeleteFeeStructure(long id){var c=await Open(HttpContext.RequestAborted);await BTech.Services.Fees.FeePlanLegacyGuard.EnsureLegacyStructureAsync(c,id);await using var q=c.CreateCommand();q.CommandText="DELETE FROM fee_structures WHERE fee_structure_id=@id";P(q,"@id",id);try{return await q.ExecuteNonQueryAsync(HttpContext.RequestAborted)>0?NoContent():NotFound(new{success=false,message="Fee structure not found."});}catch(DbException){return Conflict(new{success=false,message="Fee structure is referenced by other records and cannot be deleted."});}}
 [HttpGet("fee-components")] public async Task<IActionResult> GetComponents(){var c=await Open(HttpContext.RequestAborted);await using var q=c.CreateCommand();q.CommandText="SELECT * FROM fee_categories ORDER BY fee_category_id";await using var r=await q.ExecuteReaderAsync(HttpContext.RequestAborted);var rows=new List<object?>();while(await r.ReadAsync(HttpContext.RequestAborted))rows.Add(await Row(r,HttpContext.RequestAborted));return Ok(new{success=true,data=rows});}
 [HttpPost("fee-components")] public Task<IActionResult> CreateComponent([FromBody] JsonElement body)=>Create("fee-components",body);
 [HttpPut("fee-components/{id:long}")] public Task<IActionResult> UpdateComponent(long id,[FromBody] JsonElement body)=>Update("fee-components",id,body);
 [HttpDelete("fee-components/{id:long}")] public async Task<IActionResult> DeleteComponent(long id){var c=await Open(HttpContext.RequestAborted);await using var q=c.CreateCommand();q.CommandText="DELETE FROM fee_categories WHERE fee_category_id=@id";P(q,"@id",id);try{return await q.ExecuteNonQueryAsync(HttpContext.RequestAborted)>0?NoContent():NotFound(new{success=false,message="Fee component not found."});}catch(DbException){return Conflict(new{success=false,message="Fee component is referenced by fee structures and cannot be deleted."});}}
 [HttpPost("fee-structures/{id:long}/publish")] public async Task<IActionResult> PublishStructure(long id){var c=await Open(HttpContext.RequestAborted);await BTech.Services.Fees.FeePlanLegacyGuard.EnsureLegacyStructureAsync(c,id);return await Status("fee-structures",id,"Published");}
 [HttpGet("fee-structures/{id:long}/versions")] public async Task<IActionResult> StructureVersions(long id){var c=await Open(HttpContext.RequestAborted);await BTech.Services.Fees.FeePlanLegacyGuard.EnsureLegacyStructureAsync(c,id);return await List("fee-structure-versions",id.ToString());}
 [HttpGet("fee-assignments")] public Task<IActionResult> GetAssignments()=>List("fee-assignments");
 [HttpDelete("fee-assignments/{id:long}")] public Task<IActionResult> DeleteAssignment(long id)=>Delete("fee-assignments",id);
 [HttpGet("fee-structures/{id:long}/students")] public async Task<IActionResult> StructureStudents(long id){var c=await Open(HttpContext.RequestAborted);await BTech.Services.Fees.FeePlanLegacyGuard.EnsureLegacyStructureAsync(c,id);return await List("fee-assignments",id.ToString());}
 [HttpPost("fee-structures/{id:long}/assign")] public async Task<IActionResult> AssignStudents(long id,[FromBody] JsonElement body){var c=await Open(HttpContext.RequestAborted);await BTech.Services.Fees.FeePlanLegacyGuard.EnsureLegacyStructureAsync(c,id);return await Create("fee-assignments",body,id.ToString());}
 [HttpPost("fee-structures/{id:long}/unassign")] public async Task<IActionResult> UnassignStudents(long id,[FromBody] JsonElement body){var c=await Open(HttpContext.RequestAborted);await BTech.Services.Fees.FeePlanLegacyGuard.EnsureLegacyStructureAsync(c,id);return await Create("fee-unassignments",body,id.ToString());}
 [HttpGet("fee-collection/receipts/{id:long}/download")] public async Task<IActionResult> DownloadReceipt(long id){var c=await Open(HttpContext.RequestAborted);var x=await SelectOne(c,"SELECT * FROM fee_receipts WHERE receipt_id=@id","@id",id,HttpContext.RequestAborted);return x is null?NotFound(new{success=false,message="Receipt not found."}):Ok(new{success=true,data=x,downloadAvailable=false,message="Receipt record fetched. PDF/binary generation is not configured."});}
 [HttpGet("fee-collection/defaulters")] public Task<IActionResult> Defaulters()=>List("fee-defaulters");
 [HttpGet("fee-collection/reports/summary")] public async Task<IActionResult> FeeSummary(){var c=await Open(HttpContext.RequestAborted);await using var q=c.CreateCommand();q.CommandText="SELECT COUNT(*) FROM fee_payments";var count=Convert.ToInt64(await q.ExecuteScalarAsync(HttpContext.RequestAborted));return Ok(new{success=true,data=new{paymentCount=count}});}
 [HttpGet("fee-collection/payments/{id:long}")] public async Task<IActionResult> GetPayment(long id){var c=await Open(HttpContext.RequestAborted);var x=await SelectOne(c,"SELECT * FROM fee_payments WHERE payment_id=@id","@id",id,HttpContext.RequestAborted);return x is null?NotFound(new{success=false,message="Payment not found."}):Ok(new{success=true,data=x});}
 [HttpPost("fee-collection/payments/{id:long}/refund")] public Task<IActionResult> RefundPayment(long id,[FromBody] JsonElement body)=>Create("fee-refunds",body,id.ToString(),"Requested");
}
